ss="form-group">                                <label for="value" class="control-label">Giá trị</label>                                <input class="form-control" name="value" id="value" type="text" value="<?php echo isset($row['value']) ? $row['value'] : ''; ?>">                            </div>                        </div>                        <div class="col-md-3">                            <div class="form-group">                                <label for="value" class="control-label">Đơn vị tính</label>                                <select class="form-control" name="date_unit" id="date_unit">                                    <?php echo get_option_select($this->config->item('date_unit'), isset($row['date_unit']) ? $row['date_unit'] : ''); ?>                                </select>                            </div>                        </div>                    </div>                    <div class="text-center">                        <?php if (isset($row['id'])) : ?>                            <input class="btn btn-primary" type="submit" value="Lưu thay đổi">                        <?php else : ?>                            <input class="btn btn-success" type="submit" value="Đăng <?php echo $module_name; ?>">                        <?php endif; ?>                    </div>                </form>            </div>        </div>    </div></div>